def comprimir_repeticiones(texto: str) -> str:
    if not texto:
        return ""
    result = []
    i = 0
    n = len(texto)
    while i < n:
        ch = texto[i]
        j = i + 1
        while j < n and texto[j] == ch:
            j += 1
        count = j - i
        result.append(f"{ch}{count}")
        i = j
    return "".join(result)

def aplanar(datos: list) -> list:
    def flatten(obj):
        if isinstance(obj, (list, tuple)):
            result = []
            for element in obj:
                if isinstance(element, (list, tuple)):
                    result.extend(flatten(element))
                else:
                    result.append(element)
            return result
        else:
            # For non-list/tuple objects, wrap them as a single-element list.
            return [obj]

    result = []
    for item in datos:
        if isinstance(item, (list, tuple)):
            flat_item = flatten(item)
            result.extend(flat_item)
        else:
            result.append(item)
    return result

import csv
import io

def parsear_ventas(texto: str) -> list[dict]:
    if not texto.strip():
        return []

    reader = csv.reader(io.StringIO(texto))
    rows = list(reader)

    expected_header = ['fecha', 'producto', 'cantidad', 'precio']
    header = rows[0]
    if header != expected_header:
        raise ValueError("Cabecera no es la indicada")

    result = []
    for row in rows[1:]:
        # Skip empty lines (row may be [] or all fields are empty after stripping)
        if not row or all(cell.strip() == '' for cell in row):
            continue

        if len(row) != 4:
            raise ValueError(f"Fila tiene {len(row)} campos, esperado 4: {row}")

        fecha, producto, cantidad_str, precio_str = row

        # Convert quantity to integer
        try:
            cantidad = int(cantidad_str)
        except ValueError:
            raise ValueError(f"Cantidad no es un entero: '{cantidad_str}'")
        if cantidad < 0:
            raise ValueError(f"Cantidad negativa: {cantidad}")

        # Convert price to float
        try:
            precio = float(precio_str)
        except ValueError:
            raise ValueError(f"Precio no es un número: '{precio_str}'")

        result.append({
            'fecha': fecha,
            'producto': producto,
            'cantidad': cantidad,
            'precio': precio
        })

    return result

