def remove_accents(s):
    nfkd = unicodedata.normalize('NFD', s)
    return ''.join(ch for ch in nfkd if not unicodedata.combining(ch))

def parsear_fecha(texto: str) -> str:
    text = texto.strip()
    year = None
    month = None
    day = None

    if '-' in text:
        parts = text.split('-')
        if len(parts) != 3:
            raise ValueError("Formato inválido")
        try:
            year = int(parts[0])
            month = int(parts[1].strip())
            day = int(parts[2].strip())
        except ValueError:
            raise ValueError("Días y meses no válidos")
    elif '/' in text:
        parts = text.split('/')
        if len(parts) != 3:
            raise ValueError("Formato inválido")
        try:
            day = int(parts[0].strip())
            month = int(parts[1].strip())
            year = int(parts[2].strip())
        except ValueError:
            raise ValueError("Días y meses no válidos")
    else:
        tokens = text.split()
        if len(tokens) != 5 or tokens[1] != 'de' or tokens[3] != 'de':
            raise ValueError("Formato inválido para formato 3")
        try:
            day = int(tokens[0].strip())
            year = int(tokens[4].strip())
        except ValueError:
            raise ValueError("Día o año no válido")
        month_name = tokens[2].strip()
        # Remove accents and lowercase
        month_clean = remove_accents(month_name.lower())
        if month_clean not in MONTHS:
            raise ValueError(f"Mes '{month_name}' no reconocido.")
        month = MONTHS[month_clean]

    try:
        dt = date(year, month, day)
    except Exception as e:
        raise ValueError(f"Fecha inválida: {e}")

    return f"{year}-{month:02d}-{day:02d}"

def promedio_movil(valores: list[float], ventana: int) -> list[float]:
    if not valores or ventana <= 0 or len(valores) < ventana:
        return []
    resultado = []
    for i in range(len(valores) - ventana + 1):
        resultado.append(sum(valores[i:i + ventana]) / ventana)
    return resultado

def mochila(pesos: list[int], valores: list[int], capacidad: int) -> tuple[int, list[int]]:
    if len(pesos) != len(valores):
        raise ValueError("Lengths of pesos and valores must be equal")
    if any(p < 0 for p in pesos) or capacidad < 0:
        raise ValueError("Weights cannot be negative and capacity cannot be negative")
    n = len(pesos)
    best_key = None
    best_val = -1
    best_indices = []
    for mask in range(1 << n):
        total_weight = 0
        total_value = 0
        indices = []
        for i in range(n):
            if mask & (1 << i):
                total_weight += pesos[i]
                total_value += valores[i]
                indices.append(i)
        if total_weight > capacidad:
            continue
        key = (-total_value, total_weight, len(indices), indices)
        if best_key is None or key < best_key:
            best_key = key
            best_val = total_value
            best_indices = indices
    if best_key is None:
        return 0, []
    else:
        return best_val, best_indices

def evaluar(expresion):
    # Remove all whitespace characters from the input string
    expr = expresion.replace(' ', '')

    # Disallow a single forward slash (division by integer) but allow double slash // 
    if ('/' in expr) and '//' not in expr:
        raise ValueError("Operator '/' not allowed")

    # Unary plus is not permitted according to the specification
    if expr.startswith('+'):
        raise ValueError("Plus sign must be binary, not unary")

    try:
        result = eval(expr)
    except ZeroDivisionError:
        # Re-raise the built-in ZeroDivisionError as required
        raise
    except Exception as e:
        # Any other exception (syntax error, etc.) indicates an invalid expression
        raise ValueError(f"Invalid expression: {expresion}")

    return result

from collections import OrderedDict


class CacheLRU:
    def __init__(self, capacidad: int):
        if capacidad < 0:
            raise ValueError("Capacidad no puede ser negativa")
        self.capacidad = capacidad
        self._datos = OrderedDict()

    def get(self, clave):
        if clave in self._datos:
            self._datos.move_to_end(clave)
            return self._datos[clave]
        else:
            return None

    def put(self, clave, valor):
        if self.capacidad == 0:
            # No store anything when capacity is zero
            return
        if clave not in self._datos and len(self._datos) >= self.capacidad:
            self._datos.popitem(last=False)
        self._datos[clave] = valor

    def __len__(self):
        return len(self._datos)
